import java.util.*;

public class Main {
    // Nested loops: try every pair. Time O(N^2), space O(1).
    static String brute(int[] a, int target) {
        int checks = 0;
        for (int i = 0; i < a.length; i++)
            for (int j = i + 1; j < a.length; j++) {
                checks++;
                if (a[i] + a[j] == target)
                    return "pair (" + a[i] + ", " + a[j] + ") after " + checks + " checks";
            }
        return "no pair after " + checks + " checks";
    }

    // Two pointers on a sorted array. Time O(N), space O(1).
    static String twoPointers(int[] a, int target) {
        int L = 0, R = a.length - 1, steps = 0;
        while (L < R) {
            steps++;
            int sum = a[L] + a[R];
            if (sum == target)
                return "pair (" + a[L] + ", " + a[R] + ") after " + steps + " checks";
            if (sum < target) L++;   // a[L] is too small for every partner left
            else R--;                // a[R] is too big for every partner left
        }
        return "no pair after " + steps + " checks";
    }

    public static void main(String[] args) {
        int[] a = {1, 3, 4, 6, 8, 11, 15};   // must be sorted
        int target = 14;
        System.out.println("array: " + Arrays.toString(a) + " target: " + target);
        System.out.println("nested loops: " + brute(a, target));
        System.out.println("two pointers: " + twoPointers(a, target));
    }
}

