// Nested loops: try every pair. Time O(N^2), space O(1).
string brute(const vector<int>& a, int target) {
    int checks = 0, n = a.size();
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++) {
            checks++;
            if (a[i] + a[j] == target)
                return "pair (" + to_string(a[i]) + ", " + to_string(a[j]) + ") after " + to_string(checks) + " checks";
        }
    return "no pair after " + to_string(checks) + " checks";
}

// Two pointers on a sorted array. Time O(N), space O(1).
string twoPointers(const vector<int>& a, int target) {
    int L = 0, R = (int)a.size() - 1, steps = 0;
    while (L < R) {
        steps++;
        int sum = a[L] + a[R];
        if (sum == target)
            return "pair (" + to_string(a[L]) + ", " + to_string(a[R]) + ") after " + to_string(steps) + " checks";
        if (sum < target) L++;   // a[L] is too small for every partner left
        else R--;                // a[R] is too big for every partner left
    }
    return "no pair after " + to_string(steps) + " checks";
}

