import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] a = {2, 5, 7, 9, 12, 16};   // sorted
        int target = 16;
        System.out.println("array: " + Arrays.toString(a) + " target: " + target);
        int L = 0, R = a.length - 1;
        boolean found = false;
        // Time O(N): each step moves one pointer inward. Space O(1).
        while (L < R) {
            int sum = a[L] + a[R];
            String line = "L=" + L + " R=" + R + " sum=" + sum;
            if (sum == target) {
                System.out.println(line + " -> found " + a[L] + " + " + a[R]);
                found = true;
                break;
            } else if (sum > target) {
                // a[R] is too big even with the smallest value left, so drop it
                System.out.println(line + " too big, move R left");
                R--;
            } else {
                // a[L] is too small even with the biggest value left, so drop it
                System.out.println(line + " too small, move L right");
                L++;
            }
        }
        if (!found) System.out.println("no pair");
    }
}

