import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] a = {8, 3, 11, 5, 2};   // not sorted, and we must report indices
        int target = 13;
        System.out.println("array: " + Arrays.toString(a) + " target: " + target);
        // value -> index where we saw it. Time O(N), space O(N).
        Map<Integer, Integer> seen = new HashMap<>();
        boolean found = false;
        for (int i = 0; i < a.length; i++) {
            int need = target - a[i];          // the partner this value needs
            if (seen.containsKey(need)) {      // partner appeared earlier
                System.out.println("indices " + seen.get(need) + " and " + i
                        + " (" + need + " + " + a[i] + ")");
                found = true;
                break;
            }
            seen.put(a[i], i);                 // store AFTER the check: no self-pairing
        }
        if (!found) System.out.println("no pair");
    }
}

