import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] nums = {-1, 0, 1, 2, -1, -4, -2, 2, 0, 0};
        System.out.println("input:  " + Arrays.toString(nums));
        Arrays.sort(nums);                       // equal values become neighbours
        System.out.println("sorted: " + Arrays.toString(nums));
        int count = 0, n = nums.length;
        // Time O(N^2) after the O(N log N) sort; extra space O(1).
        for (int i = 0; i < n - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;   // same first value: skip
            int L = i + 1, R = n - 1;
            while (L < R) {
                int sum = nums[i] + nums[L] + nums[R];
                if (sum < 0) L++;
                else if (sum > 0) R--;
                else {
                    System.out.println("[" + nums[i] + ", " + nums[L] + ", " + nums[R] + "]");
                    count++;
                    // record first, THEN jump over the copies of both values
                    while (L < R && nums[L] == nums[L + 1]) L++;
                    while (L < R && nums[R] == nums[R - 1]) R--;
                    L++;
                    R--;
                }
            }
        }
        System.out.println("unique triplets: " + count);
    }
}

