    for (const auto& h : tests) {
        cout << "heights: [";
        for (size_t i = 0; i < h.size(); i++) cout << (i ? ", " : "") << h[i];
        cout << "] two pointers: " << maxArea(h) << " brute force: " << brute(h) << "\n";
    }
}

