using System;

class Program {
    // Two pointers. Time O(N), space O(1).
    static int MaxArea(int[] h) {
        int L = 0, R = h.Length - 1, best = 0;
        while (L < R) {
            int area = Math.Min(h[L], h[R]) * (R - L);   // water level = shorter wall
            best = Math.Max(best, area);
            if (h[L] < h[R]) L++;   // the shorter wall can never do better: drop it
            else R--;
        }
        return best;
    }

    // Every pair of walls. Time O(N^2). Used only to check the fast answer.
    static int Brute(int[] h) {
        int best = 0;
        for (int i = 0; i < h.Length; i++)
            for (int j = i + 1; j < h.Length; j++)
                best = Math.Max(best, Math.Min(h[i], h[j]) * (j - i));
        return best;
    }

    static void Main() {
        int[][] tests = { new int[] {1, 8, 6, 2, 5, 4, 8, 3, 7}, new int[] {2, 9, 1, 9} };
        foreach (int[] h in tests)
            Console.WriteLine("heights: [" + string.Join(", ", h) + "] two pointers: "
                    + MaxArea(h) + " brute force: " + Brute(h));
    }
}

