import java.util.*;

public class Main {
    // Keep one copy of each value in a sorted array. Time O(N), space O(1).
    static int dedupe(int[] a) {
        int slow = 0;                               // next free cell for a kept value
        for (int fast = 0; fast < a.length; fast++) // fast reads every element once
            if (slow == 0 || a[fast] != a[slow - 1])   // keep rule: differs from last kept
                a[slow++] = a[fast];
        return slow;                                // a[0..slow-1] is the answer
    }

    // Same template, keep rule "non-zero", then fill the tail with zeroes.
    static void moveZeroes(int[] a) {
        int slow = 0;
        for (int fast = 0; fast < a.length; fast++)
            if (a[fast] != 0) a[slow++] = a[fast];
        while (slow < a.length) a[slow++] = 0;
    }

    public static void main(String[] args) {
        int[] a = {1, 1, 2, 2, 2, 3, 5, 5};
        System.out.println("sorted input: " + Arrays.toString(a));
        int k = dedupe(a);
        System.out.println("kept " + k + " values: " + Arrays.toString(Arrays.copyOf(a, k)));

        int[] b = {0, 3, 0, 0, 7, 1, 0};
        System.out.println("input: " + Arrays.toString(b));
        moveZeroes(b);
        System.out.println("zeroes moved to the end: " + Arrays.toString(b));
    }
}

