import java.util.*;

public class Main {
    // Fixed size: the length K is given. Time O(N), space O(1).
    static int maxSumOfK(int[] a, int k) {
        int sum = 0;
        for (int i = 0; i < k; i++) sum += a[i];   // build the first window
        int best = sum;
        for (int i = k; i < a.length; i++) {
            sum += a[i] - a[i - k];                // one comes in, one goes out
            best = Math.max(best, sum);
        }
        return best;
    }

    // Variable size: we search for the length. Positive numbers only.
    // Time O(N), space O(1). Returns 0 if no window reaches the target.
    static int shortestAtLeast(int[] a, int target) {
        int L = 0, sum = 0, best = a.length + 1;
        for (int R = 0; R < a.length; R++) {
            sum += a[R];                           // grow on the right
            while (sum >= target) {                // good window: record, then shrink
                best = Math.min(best, R - L + 1);
                sum -= a[L++];
            }
        }
        return best == a.length + 1 ? 0 : best;
    }

    public static void main(String[] args) {
        int[] a = {2, 1, 5, 1, 3, 2};
        System.out.println("fixed:    " + Arrays.toString(a) + " K=3 -> max window sum = "
                + maxSumOfK(a, 3));
        int[] b = {2, 3, 1, 2, 4, 3};
        System.out.println("variable: " + Arrays.toString(b) + " target=7 -> shortest length = "
                + shortestAtLeast(b, 7));
    }
}

