import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] a = {4, 2, 1, 7, 8, 1, 2, 8, 1, 0};
        int limit = 8;                 // longest window with sum <= limit
        int n = a.length;
        System.out.println("array: " + Arrays.toString(a) + " limit: " + limit);
        int L = 0, sum = 0, best = 0;
        int adds = 0, removes = 0;     // counters for the amortised argument
        // Time O(N) in total, space O(1).
        for (int R = 0; R < n; R++) {
            sum += a[R];
            adds++;                    // each index enters the window once
            while (sum > limit) {      // inner loop: L only ever moves forward
                sum -= a[L++];
                removes++;             // each index leaves at most once
            }
            best = Math.max(best, R - L + 1);
        }
        System.out.println("longest window length: " + best);
        System.out.println("adds: " + adds + ", removes: " + removes);
        System.out.println("total moves " + (adds + removes) + " <= 2N = " + (2 * n)
                + ", while N*N = " + (n * n));
    }
}

