import java.util.*;

public class Main {
    // Shortest subarray with sum >= k using a window. WRONG if negatives exist.
    static int windowShortest(int[] a, int k) {
        int L = 0, sum = 0, best = a.length + 1;
        for (int R = 0; R < a.length; R++) {
            sum += a[R];
            while (sum >= k) {              // assumes shrinking always lowers the sum
                best = Math.min(best, R - L + 1);
                sum -= a[L++];
            }
        }
        return best;
    }

    // Try every subarray: always right, O(N^2).
    static int bruteShortest(int[] a, int k) {
        int best = a.length + 1;
        for (int i = 0; i < a.length; i++) {
            int sum = 0;
            for (int j = i; j < a.length; j++) {
                sum += a[j];
                if (sum >= k) best = Math.min(best, j - i + 1);
            }
        }
        return best;
    }

    // Count subarrays with sum exactly k. Time O(N), space O(N). Negatives are fine.
    static int countExact(int[] a, int k) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, 1);                     // the empty prefix
        int prefix = 0, count = 0;
        for (int x : a) {
            prefix += x;
            count += seen.getOrDefault(prefix - k, 0);   // earlier prefixes that fit
            seen.put(prefix, seen.getOrDefault(prefix, 0) + 1);
        }
        return count;
    }

    public static void main(String[] args) {
        int[] a = {1, -1, 5};
        int k = 5;
        System.out.println("array: " + Arrays.toString(a) + " k: " + k);
        System.out.println("window says shortest length:  " + windowShortest(a, k));
        System.out.println("brute force says:             " + bruteShortest(a, k));
        System.out.println("subarrays with sum exactly k: " + countExact(a, k));
    }
}

