    static int CountExact(int[] a, int k) {
        Dictionary<int, int> seen = new Dictionary<int, int>();
        seen[0] = 1;                        // the empty prefix
        int prefix = 0, count = 0, c;
        foreach (int x in a) {
            prefix += x;
            if (seen.TryGetValue(prefix - k, out c)) count += c;   // earlier prefixes that fit
            seen[prefix] = (seen.TryGetValue(prefix, out c) ? c : 0) + 1;
        }
        return count;
    }

    static void Main() {
        int[] a = {1, -1, 5};
        int k = 5;
        Console.WriteLine("array: [" + string.Join(", ", a) + "] k: " + k);
        Console.WriteLine("window says shortest length:  " + WindowShortest(a, k));
        Console.WriteLine("brute force says:             " + BruteShortest(a, k));
        Console.WriteLine("subarrays with sum exactly k: " + CountExact(a, k));
    }
}

