import java.util.*;

public class Main {
    // Number of subarrays with at most k distinct values (values are 0..9).
    // Time O(N), space O(1) because the count array has a fixed size.
    static int atMost(int[] a, int k) {
        int[] freq = new int[10];
        int L = 0, distinct = 0, total = 0;
        for (int R = 0; R < a.length; R++) {
            if (freq[a[R]]++ == 0) distinct++;          // a new value entered
            while (distinct > k)                        // too many: shrink from the left
                if (--freq[a[L++]] == 0) distinct--;
            total += R - L + 1;     // every start from L to R gives a valid subarray ending at R
        }
        return total;
    }

    public static void main(String[] args) {
        int[] a = {1, 2, 1, 2, 3};
        int k = 2;
        System.out.println("array: " + Arrays.toString(a) + " K: " + k);
        int upTo = atMost(a, k), below = atMost(a, k - 1);
        System.out.println("atMost(" + k + ") = " + upTo);
        System.out.println("atMost(" + (k - 1) + ") = " + below);
        // "exactly K" is what is left after removing "K-1 or fewer"
        System.out.println("exactly " + k + " distinct = " + (upTo - below));
    }
}

