import java.util.*;

public class Main {
    // Time O(N), space O(1): no prefix-max or suffix-max arrays.
    static int trap(int[] h) {
        int L = 0, R = h.length - 1;
        int leftMax = 0, rightMax = 0, water = 0;
        while (L < R) {
            if (h[L] < h[R]) {
                // a wall at least as tall as leftMax exists on the right,
                // so the water level above bar L is decided by leftMax alone
                leftMax = Math.max(leftMax, h[L]);
                water += leftMax - h[L];
                L++;
            } else {
                // mirror case: bar R is decided by rightMax alone
                rightMax = Math.max(rightMax, h[R]);
                water += rightMax - h[R];
                R--;
            }
        }
        return water;
    }

    public static void main(String[] args) {
        int[][] tests = {{0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1}, {4, 2, 0, 3, 2, 5}, {1, 2, 3}};
        for (int[] h : tests)
            System.out.println("heights: " + Arrays.toString(h) + " -> water: " + trap(h));
    }
}

