import java.util.*;

public class Main {
    public static void main(String[] args) {
        int limit = 3, windowSec = 10;
        int[] times = {1, 2, 3, 5, 11, 12, 13, 14, 25};   // request times in seconds
        System.out.println("limit: " + limit + " requests per " + windowSec + " s");
        System.out.println("request times: " + Arrays.toString(times));
        // The queue holds the times of accepted requests still inside the window.
        // Time O(1) amortised per request, space O(limit).
        Deque<Integer> recent = new ArrayDeque<>();
        for (int t : times) {
            // left edge of the window moves forward: drop requests that are too old
            while (!recent.isEmpty() && recent.peekFirst() <= t - windowSec)
                recent.pollFirst();
            if (recent.size() < limit) {
                recent.addLast(t);                 // right edge: the new request enters
                System.out.println("t=" + t + " ALLOW (in window: " + recent.size() + ")");
            } else {
                System.out.println("t=" + t + " DENY  (in window: " + recent.size() + ")");
            }
        }
    }
}

