using System;
using System.Collections.Generic;

class Program {
    static void Main() {
        int limit = 3, windowSec = 10;
        int[] times = {1, 2, 3, 5, 11, 12, 13, 14, 25};   // request times in seconds
        Console.WriteLine("limit: " + limit + " requests per " + windowSec + " s");
        Console.WriteLine("request times: [" + string.Join(", ", times) + "]");
        // The queue holds the times of accepted requests still inside the window.
        // Time O(1) amortised per request, space O(limit).
        Queue<int> recent = new Queue<int>();
        foreach (int t in times) {
            // left edge of the window moves forward: drop requests that are too old
            while (recent.Count > 0 && recent.Peek() <= t - windowSec)
                recent.Dequeue();
            if (recent.Count < limit) {
                recent.Enqueue(t);                 // right edge: the new request enters
                Console.WriteLine("t=" + t + " ALLOW (in window: " + recent.Count + ")");
            } else {
                Console.WriteLine("t=" + t + " DENY  (in window: " + recent.Count + ")");
            }
        }
    }
}

