import java.util.*;

public class Main {
    static int seed = 7;
    // Tiny fixed random generator, so every run produces the same tests.
    static int next() { seed = (seed * 75 + 74) % 65537; return seed; }

    // Window: longest subarray with sum <= k (positive numbers). Time O(N), space O(1).
    static int fast(int[] a, int k) {
        int L = 0, sum = 0, best = 0;
        for (int R = 0; R < a.length; R++) {
            sum += a[R];
            while (sum > k) sum -= a[L++];   // safe only because all values are positive
            best = Math.max(best, R - L + 1);
        }
        return best;
    }

    // Every subarray. Time O(N^2). Slow but obviously right.
    static int brute(int[] a, int k) {
        int best = 0;
        for (int i = 0; i < a.length; i++) {
            int sum = 0;
            for (int j = i; j < a.length; j++) {
                sum += a[j];
                if (sum <= k) best = Math.max(best, j - i + 1);
            }
        }
        return best;
    }

    public static void main(String[] args) {
        int tests = 200, mismatches = 0;
        for (int t = 0; t < tests; t++) {
            int[] a = new int[next() % 8 + 1];              // length 1..8
            for (int i = 0; i < a.length; i++) a[i] = next() % 9 + 1;   // values 1..9
            int k = next() % 20 + 1;
            int f = fast(a, k), b = brute(a, k);
            if (t == 0)
                System.out.println("sample: " + Arrays.toString(a) + " k=" + k
                        + " window=" + f + " brute=" + b);
            if (f != b) mismatches++;                       // a mismatch would expose a bug
        }
        System.out.println("tests: " + tests + ", mismatches: " + mismatches);
    }
}

